
.status-bar {
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 100%;
  overflow-y: auto;
}

.sb-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 4px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.sb-title {
  font-size: 14px;
  font-weight: 700;
  color: #c084fc;
}

.sb-day {
  font-size: 11px;
  color: #94a3b8;
}

.sb-section {
  background: rgba(255, 255, 255, 0.05);
  border-radius: 6px;
  padding: 6px 8px;
}

.sb-label {
  font-size: 10px;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 2px;
}

.sb-value {
  font-size: 12px;
  color: #e2e8f0;
}

.sb-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.sb-stat {
  font-size: 12px;
  color: #e2e8f0;
}

.sb-fairy-name {
  font-size: 13px;
  font-weight: 600;
  color: #f472b6;
  margin-bottom: 2px;
}

.sb-tag {
  font-size: 10px;
  background: rgba(255, 255, 255, 0.08);
  color: #94a3b8;
  padding: 1px 6px;
  border-radius: 3px;
}

.sb-mods {
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
  margin-top: 4px;
}

.sb-tag-mod {
  font-size: 9px;
  background: rgba(168, 85, 247, 0.3);
  color: #e2e8f0;
  padding: 1px 5px;
  border-radius: 3px;
}

.sb-fairy-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 3px 6px;
  border-radius: 4px;
  font-size: 11px;
  background: rgba(255, 255, 255, 0.05);
  margin-top: 2px;
}

.sb-fairy-item.active {
  border: 1px solid #f472b6;
}

.sb-fairy-entry {
  color: #e2e8f0;
  font-weight: 500;
}

.sb-fairy-stats {
  color: #94a3b8;
  font-size: 10px;
}
